import unittest
from candidate import below_zero

class TestBelowZero(unittest.TestCase):
    def test_below_zero_normal_positive_operations_returns_false(self):
        self.assertFalse(below_zero([1, 2, 3]))

    def test_below_zero_normal_below_zero_returns_true(self):
        self.assertTrue(below_zero([1, 2, -4, 5]))

    def test_below_zero_empty_list_returns_false(self):
        self.assertFalse(below_zero([]))

    def test_below_zero_single_negative_returns_true(self):
        self.assertTrue(below_zero([-1]))

    def test_below_zero_single_positive_returns_false(self):
        self.assertFalse(below_zero([5]))

    def test_below_zero_balance_never_dips_below_zero_returns_false(self):
        self.assertFalse(below_zero([1, -1, 2]))

    def test_below_zero_balance_dips_below_zero_then_recoveres_still_true(self):
        self.assertTrue(below_zero([-1, 1]))

    def test_below_zero_list_with_zero_operations_returns_false(self):
        self.assertFalse(below_zero([0, 0, 0]))

    def test_below_zero_type_error_on_none_input(self):
        with self.assertRaises(TypeError):
            below_zero(None)

    def test_below_zero_type_error_on_string_in_list(self):
        with self.assertRaises(TypeError):
            below_zero([1, "a"])

    def test_below_zero_type_error_on_dict_input(self):
        with self.assertRaises(TypeError):
            below_zero({"a": 1})

    def test_below_zero_multiple_withdrawals_triggers_negative(self):
        self.assertTrue(below_zero([2, -3, -1]))

    def test_below_zero_large_deposit_then_large_withdrawal(self):
        self.assertTrue(below_zero([100, -200]))

    def test_below_zero_sequence_goes_negative_at_end(self):
        self.assertTrue(below_zero([5, 3, -10]))
